const q = (id, domain, level, order, difficulty, title, name, role, request, notes, concepts, cols, sql, order_sensitive, hints, explanation, xp, mins) => ({
  id, domain, level, order, difficulty, title,
  stakeholder: { name, role },
  request, context_notes: notes, concepts,
  expected_columns: cols,
  reference_sql: sql,
  validation: { order_sensitive: order_sensitive === 't', column_names_sensitive: false, numeric_tolerance: 0 },
  hints: Array.isArray(hints) ? hints : [hints],
  solution_explanation: explanation,
  xp, estimated_minutes: mins
});

const L3 = [
  // WARM-UP 1–25: Subqueries IN / NOT IN, Supply Chain Basics
  q('rest-L3-001','restaurants',3,1,'warm-up','High-Rated Suppliers','Chef Marco Vieri','Executive Chef & Founder','We need to review our premium vendor roster — pull all suppliers who maintain a quality rating of 4.8 or higher.','Filter suppliers table by rating >= 4.8.',['SELECT','WHERE'],['supplier_name','category','rating'],"SELECT supplier_name, category, rating FROM suppliers WHERE rating >= 4.8 ORDER BY rating DESC, supplier_name;",'t',['Query suppliers table with WHERE rating >= 4.8.','Order by rating DESC, supplier_name.'],'Filters suppliers meeting the executive quality threshold.',25,5),
  q('rest-L3-002','restaurants',3,2,'warm-up','Low Stock Raw Ingredients','Chef Marco Vieri','Executive Chef & Founder','Which raw ingredients are running low? Show anything with current stock below 100 units so the prep team can reorder.','Filter ingredients where current_stock_qty < 100.',['SELECT','WHERE'],['ingredient_name','category','current_stock_qty'],"SELECT ingredient_name, category, current_stock_qty FROM ingredients WHERE current_stock_qty < 100 ORDER BY current_stock_qty ASC;",'t',['Filter ingredients table with WHERE current_stock_qty < 100.','Sort ascending by stock to spot most urgent items.'],'Spots low-stock ingredients for immediate replenishment.',25,5),
  q('rest-L3-003','restaurants',3,3,'warm-up','Total Spend With Verona Importers','Elena Rossi','Beverage & Cellar Director','How much have we spent in total with Verona Italian Importers for our cellar and pantry imports?','JOIN ingredient_purchases with suppliers for Verona Italian Importers.',['SELECT','INNER JOIN','SUM'],['total_spend'],"SELECT SUM(ip.total_amount) AS total_spend FROM ingredient_purchases ip JOIN suppliers s ON ip.supplier_id = s.id WHERE s.supplier_name = 'Verona Italian Importers';",'f',['Join ingredient_purchases ip with suppliers s on ip.supplier_id = s.id.','Filter WHERE s.supplier_name = Verona Italian Importers.'],'Calculates cumulative procurement spend with key vendor.',25,5),
  q('rest-L3-004','restaurants',3,4,'warm-up','Venues Purchasing From Organic Meats','Chef Marco Vieri','Executive Chef & Founder','Which of our restaurants have active procurement orders with Hudson Valley Organic Meats?','Subquery or JOIN on ingredient_purchases with suppliers and restaurants.',['SELECT','DISTINCT','INNER JOIN'],['restaurant_name'],"SELECT DISTINCT r.name AS restaurant_name FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id JOIN suppliers s ON ip.supplier_id = s.id WHERE s.supplier_name = 'Hudson Valley Organic Meats' ORDER BY r.name;",'f',['Join restaurants, ingredient_purchases, and suppliers.','Filter WHERE s.supplier_name = Hudson Valley Organic Meats.'],'Lists all venues sourcing organic meats.',25,5),
  q('rest-L3-005','restaurants',3,5,'warm-up','Purchases Over $2000','Giulia Conti','Director of Hospitality','For corporate audit review, pull all individual ingredient purchase invoices exceeding $2,000 with the venue name.','JOIN ingredient_purchases with restaurants where total_amount > 2000.',['SELECT','INNER JOIN','WHERE'],['restaurant_name','total_amount','purchase_date'],"SELECT r.name AS restaurant_name, ip.total_amount, ip.purchase_date FROM ingredient_purchases ip JOIN restaurants r ON ip.restaurant_id = r.id WHERE ip.total_amount > 2000 ORDER BY ip.total_amount DESC;",'t',['Join ingredient_purchases with restaurants.','Filter WHERE ip.total_amount > 2000.'],'Identifies large procurement invoices requiring audit sign-off.',25,5),
  q('rest-L3-006','restaurants',3,6,'warm-up','Ingredients Costing Over $10 Per Unit','Chef Marco Vieri','Executive Chef & Founder','Identify our high-value inventory items — show all ingredients where the unit cost is at least $10.','Filter ingredients where unit_cost >= 10.00.',['SELECT','WHERE'],['ingredient_name','category','unit_cost'],"SELECT ingredient_name, category, unit_cost FROM ingredients WHERE unit_cost >= 10.00 ORDER BY unit_cost DESC;",'t',['Filter ingredients table with WHERE unit_cost >= 10.00.','Order by unit_cost DESC.'],'Surfaces high-cost culinary inventory.',25,5),
  q('rest-L3-007','restaurants',3,7,'warm-up','Total Inventory Asset Valuation','Chef Marco Vieri','Executive Chef & Founder','What is the total dollar valuation of our on-hand pantry and cellar inventory right now?','SUM(unit_cost * current_stock_qty) from ingredients.',['SELECT','SUM','Arithmetic'],['total_inventory_value'],"SELECT ROUND(SUM(unit_cost * current_stock_qty), 2) AS total_inventory_value FROM ingredients;",'f',['Multiply unit_cost by current_stock_qty for each item.','Sum across all ingredients and round to 2 decimals.'],'Calculates total balance-sheet inventory valuation.',25,5),
  q('rest-L3-008','restaurants',3,8,'warm-up','Suppliers in Meat and Seafood','Chef Marco Vieri','Executive Chef & Founder','Pull all suppliers specializing in either Meat or Seafood along with their quality rating.','Filter suppliers table WHERE category IN (Meat, Seafood).',['SELECT','WHERE','IN'],['supplier_name','category','rating'],"SELECT supplier_name, category, rating FROM suppliers WHERE category IN ('Meat', 'Seafood') ORDER BY category, rating DESC;",'f',['Query suppliers with WHERE category IN (Meat, Seafood).','Order by category, rating DESC.'],'Surfaces animal protein vendors for quality benchmarking.',25,5),
  q('rest-L3-009','restaurants',3,9,'warm-up','Restaurants Without Purchases','Chef Marco Vieri','Executive Chef & Founder','Are there any restaurant locations that have recorded zero ingredient purchase records in our system?','Subquery NOT IN on ingredient_purchases.',['SELECT','WHERE','NOT IN'],['restaurant_name'],"SELECT name AS restaurant_name FROM restaurants WHERE id NOT IN (SELECT DISTINCT restaurant_id FROM ingredient_purchases) ORDER BY name;",'f',['Subquery: SELECT DISTINCT restaurant_id FROM ingredient_purchases.','Outer: SELECT name FROM restaurants WHERE id NOT IN (...).'],'Finds venues lacking procurement transactions.',25,6),
  q('rest-L3-010','restaurants',3,10,'warm-up','Dishes More Expensive Than Average','Chef Marco Vieri','Executive Chef & Founder','Show every menu item whose menu price is higher than the overall average dish price across our restaurants.','WHERE price > (SELECT AVG(price) FROM menu_items).',['SELECT','WHERE','Subquery','AVG'],['name','price'],"SELECT name, price FROM menu_items WHERE price > (SELECT AVG(price) FROM menu_items) ORDER BY price DESC;",'t',['Subquery: SELECT AVG(price) FROM menu_items.','Outer: Filter WHERE price > (subquery).'],'Surfaces above-average price items for luxury menu positioning.',25,6),
  q('rest-L3-011','restaurants',3,11,'warm-up','Dry Goods Inventory Valuation','Elena Rossi','Beverage & Cellar Director','What is the total dollar value of our Dry Goods inventory currently on hand?','SUM(unit_cost * current_stock_qty) WHERE category = Dry Goods.',['SELECT','SUM','WHERE','Arithmetic'],['dry_goods_value'],"SELECT ROUND(SUM(unit_cost * current_stock_qty), 2) AS dry_goods_value FROM ingredients WHERE category = 'Dry Goods';",'f',['Filter WHERE category = Dry Goods.','Sum unit_cost * current_stock_qty.'],'Evaluates dry storage stock value.',25,5),
  q('rest-L3-012','restaurants',3,12,'warm-up','Purchases Handled by Artisan Dairy Guild','Chef Marco Vieri','Executive Chef & Founder','Show all individual invoice amounts and dates for cheese and butter orders from Artisan Dairy Guild.','JOIN ingredient_purchases with suppliers for Artisan Dairy Guild.',['SELECT','INNER JOIN','WHERE'],['total_amount','purchase_date'],"SELECT ip.total_amount, ip.purchase_date FROM ingredient_purchases ip JOIN suppliers s ON ip.supplier_id = s.id WHERE s.supplier_name = 'Artisan Dairy Guild' ORDER BY ip.purchase_date DESC, ip.total_amount DESC;",'f',['Join ingredient_purchases with suppliers.','Filter WHERE s.supplier_name = Artisan Dairy Guild.'],'Reviews dairy procurement billing lines.',25,5),
  q('rest-L3-013','restaurants',3,13,'warm-up','Top 3 Priciest Ingredients','Chef Marco Vieri','Executive Chef & Founder','Which 3 ingredients carry our highest per-unit cost? Name, category, and unit cost.','ORDER BY unit_cost DESC LIMIT 3.',['SELECT','ORDER BY','LIMIT'],['ingredient_name','category','unit_cost'],"SELECT ingredient_name, category, unit_cost FROM ingredients ORDER BY unit_cost DESC LIMIT 3;",'t',['Order by unit_cost DESC and LIMIT 3.'],'Identifies our top cost-driver raw ingredients.',25,5),
  q('rest-L3-014','restaurants',3,14,'warm-up','Dishes With Cost Above Median Sample','Chef Marco Vieri','Executive Chef & Founder','List all dishes where the raw food cost is strictly greater than $10.00 per portion.','Filter menu_items WHERE cost > 10.00.',['SELECT','WHERE'],['name','cost','price'],"SELECT name, cost, price FROM menu_items WHERE cost > 10.00 ORDER BY cost DESC;",'t',['Query menu_items with WHERE cost > 10.00.','Order by cost DESC.'],'Highlights high food-cost menu offerings.',25,5),
  q('rest-L3-015','restaurants',3,15,'warm-up','Suppliers Supplying All Venues Check','Giulia Conti','Director of Hospitality','Show all supplier names alongside their assigned category and rating for the vendor directory.','Simple SELECT from suppliers.',['SELECT','ORDER BY'],['supplier_name','category','rating'],"SELECT supplier_name, category, rating FROM suppliers ORDER BY supplier_name;",'f',['Select supplier_name, category, rating from suppliers.','Order alphabetically by supplier_name.'],'Vendor directory for operations binder.',25,5),
  q('rest-L3-016','restaurants',3,16,'warm-up','Ingredients With Stock Exceeding 200','Chef Marco Vieri','Executive Chef & Founder','Which ingredients do we have comfortable inventory for — current stock of at least 200 units?','Filter ingredients WHERE current_stock_qty >= 200.',['SELECT','WHERE'],['ingredient_name','current_stock_qty'],"SELECT ingredient_name, current_stock_qty FROM ingredients WHERE current_stock_qty >= 200 ORDER BY current_stock_qty DESC;",'t',['Query ingredients with WHERE current_stock_qty >= 200.'],'Verifies well-stocked ingredients.',25,5),
  q('rest-L3-017','restaurants',3,17,'warm-up','Flagship Trattoria Total Procurement Spend','Chef Marco Vieri','Executive Chef & Founder','What is the total procurement expenditure recorded so far for our Gusto Flagship Trattoria?','JOIN ingredient_purchases with restaurants WHERE name = Gusto Flagship Trattoria.',['SELECT','INNER JOIN','SUM'],['flagship_spend'],"SELECT SUM(ip.total_amount) AS flagship_spend FROM ingredient_purchases ip JOIN restaurants r ON ip.restaurant_id = r.id WHERE r.name = 'Gusto Flagship Trattoria';",'f',['Join ingredient_purchases with restaurants.','Filter WHERE r.name = Gusto Flagship Trattoria and SUM.'],'Total procurement cost for the flagship venue.',25,5),
  q('rest-L3-018','restaurants',3,18,'warm-up','Ingredients in the Produce Category','Chef Marco Vieri','Executive Chef & Founder','List all produce ingredients we track, showing unit cost and stock on hand.','Filter ingredients WHERE category = Produce.',['SELECT','WHERE'],['ingredient_name','unit_cost','current_stock_qty'],"SELECT ingredient_name, unit_cost, current_stock_qty FROM ingredients WHERE category = 'Produce' ORDER BY ingredient_name;",'f',['Filter ingredients table with WHERE category = Produce.'],'Produce inventory review for freshness checking.',25,5),
  q('rest-L3-019','restaurants',3,19,'warm-up','Vendors Rated Exactly 4.9','Chef Marco Vieri','Executive Chef & Founder','Which of our suppliers have achieved an elite rating of exactly 4.9 out of 5.0?','Filter suppliers WHERE rating = 4.9.',['SELECT','WHERE'],['supplier_name','category'],"SELECT supplier_name, category FROM suppliers WHERE rating = 4.9 ORDER BY supplier_name;",'f',['Filter suppliers table with WHERE rating = 4.9.'],'Finds top tier vendors with 4.9 rating.',25,5),
  q('rest-L3-020','restaurants',3,20,'warm-up','Orders Larger Than Average Order Amount','Giulia Conti','Director of Hospitality','Show all dining orders where the guest bill was higher than the company-wide average order total.','WHERE total_amount > (SELECT AVG(total_amount) FROM orders).',['SELECT','WHERE','Subquery','AVG'],['id','total_amount','server_name'],"SELECT id, total_amount, server_name FROM orders WHERE total_amount > (SELECT AVG(total_amount) FROM orders) ORDER BY total_amount DESC;",'t',['Subquery calculates AVG(total_amount) from orders.','Outer query filters WHERE total_amount > average.'],'Surfaces big-ticket dining checks.',25,6),
  q('rest-L3-021','restaurants',3,21,'warm-up','Smallest Ingredient Purchase Recorded','Elena Rossi','Beverage & Cellar Director','What was the smallest individual purchase amount recorded across all supplier transactions?','MIN(total_amount) from ingredient_purchases.',['SELECT','MIN'],['min_purchase_amount'],"SELECT MIN(total_amount) AS min_purchase_amount FROM ingredient_purchases;",'f',['Select MIN(total_amount) from ingredient_purchases.'],'Finds minimum procurement ticket size.',25,5),
  q('rest-L3-022','restaurants',3,22,'warm-up','Dairy Inventory Items Valuation','Chef Marco Vieri','Executive Chef & Founder','List each dairy ingredient with its individual total inventory holding value (unit cost times stock).','SELECT ingredient_name, unit_cost * current_stock_qty WHERE category = Dairy.',['SELECT','WHERE','Arithmetic'],['ingredient_name','holding_value'],"SELECT ingredient_name, ROUND(unit_cost * current_stock_qty, 2) AS holding_value FROM ingredients WHERE category = 'Dairy' ORDER BY holding_value DESC;",'t',['Filter WHERE category = Dairy.','Multiply unit_cost by current_stock_qty.'],'Evaluates dairy inventory risk and cash tie-up.',25,5),
  q('rest-L3-023','restaurants',3,23,'warm-up','Total Number of Supplier Purchase Invoices','Giulia Conti','Director of Hospitality','How many total procurement invoices have been entered into the system to date?','COUNT(*) from ingredient_purchases.',['SELECT','COUNT'],['total_invoices'],"SELECT COUNT(*) AS total_invoices FROM ingredient_purchases;",'f',['Select COUNT(*) AS total_invoices from ingredient_purchases.'],'Counts total procurement vouchers.',25,5),
  q('rest-L3-024','restaurants',3,24,'warm-up','Dishes With Profit Margin Above $20','Chef Marco Vieri','Executive Chef & Founder','Show dishes where our unit gross profit (price minus cost) is strictly higher than $20.00.','Filter menu_items WHERE price - cost > 20.',['SELECT','WHERE','Arithmetic'],['name','price','cost','unit_profit'],"SELECT name, price, cost, ROUND(price - cost, 2) AS unit_profit FROM menu_items WHERE price - cost > 20.00 ORDER BY unit_profit DESC;",'t',['Calculate price - cost AS unit_profit.','Filter WHERE price - cost > 20.00.'],'Identifies core high-margin profit drivers.',25,5),
  q('rest-L3-025','restaurants',3,25,'warm-up','Average Purchase Invoice by Category','Elena Rossi','Beverage & Cellar Director','Join our purchases to suppliers and compute the average invoice size for each supplier category.','JOIN ingredient_purchases with suppliers, GROUP BY category.',['SELECT','INNER JOIN','AVG','GROUP BY'],['category','avg_invoice_amount'],"SELECT s.category, ROUND(AVG(ip.total_amount), 2) AS avg_invoice_amount FROM ingredient_purchases ip JOIN suppliers s ON ip.supplier_id = s.id GROUP BY s.category ORDER BY avg_invoice_amount DESC;",'t',['Join ingredient_purchases with suppliers.','Group by s.category and take AVG(ip.total_amount).'],'Benchmarks procurement order sizes across supply categories.',25,6),

  // CORE 26–50: Multi-Table Joins, Supply-Chain Aggregations & Subqueries
  q('rest-L3-026','restaurants',3,26,'core','Supplier Spend Breakdown','Chef Marco Vieri','Executive Chef & Founder','Give me our total spend with every single supplier: supplier name, category, rating, and total dollar amount paid.','JOIN suppliers with ingredient_purchases, GROUP BY supplier.',['SELECT','INNER JOIN','SUM','GROUP BY','ORDER BY'],['supplier_name','category','rating','total_spend'],"SELECT s.supplier_name, s.category, s.rating, SUM(ip.total_amount) AS total_spend FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id GROUP BY s.supplier_name, s.category, s.rating ORDER BY total_spend DESC;",'t',['Join suppliers s with ingredient_purchases ip on s.id = ip.supplier_id.','Group by supplier details and calculate SUM(ip.total_amount).'],'Ranks supplier relationships by cumulative procurement volume.',25,6),
  q('rest-L3-027','restaurants',3,27,'core','Procurement Spend Per Restaurant','Giulia Conti','Director of Hospitality','How much has each restaurant spent on ingredient purchases? Show venue name, city, and total procurement spend.','JOIN restaurants with ingredient_purchases, GROUP BY restaurant.',['SELECT','INNER JOIN','SUM','GROUP BY','ORDER BY'],['restaurant_name','city','total_purchases'],"SELECT r.name AS restaurant_name, r.city, SUM(ip.total_amount) AS total_purchases FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id GROUP BY r.name, r.city ORDER BY total_purchases DESC;",'t',['Join restaurants with ingredient_purchases.','Group by r.name, r.city and calculate SUM(ip.total_amount).'],'Compares venue-level food procurement budgets.',25,6),
  q('rest-L3-028','restaurants',3,28,'core','Inventory Value by Ingredient Category','Chef Marco Vieri','Executive Chef & Founder','Break down total inventory valuation by ingredient category — which category ties up the most cash?','GROUP BY category, SUM(unit_cost * current_stock_qty).',['SELECT','SUM','Arithmetic','GROUP BY','ORDER BY'],['category','category_value'],"SELECT category, ROUND(SUM(unit_cost * current_stock_qty), 2) AS category_value FROM ingredients GROUP BY category ORDER BY category_value DESC;",'t',['Group by category on ingredients table.','Compute SUM(unit_cost * current_stock_qty) as category_value.'],'Capital allocation breakdown across food supply categories.',25,6),
  q('rest-L3-029','restaurants',3,29,'core','Venues Spending Above Average Procurement','Chef Marco Vieri','Executive Chef & Founder','Which restaurants have total procurement spend exceeding the average venue spend across all active locations?','HAVING SUM(ip.total_amount) > (SELECT AVG of venue sums).',['SELECT','INNER JOIN','SUM','GROUP BY','HAVING','Subquery'],['restaurant_name','total_spend'],"SELECT r.name AS restaurant_name, SUM(ip.total_amount) AS total_spend FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id GROUP BY r.name HAVING SUM(ip.total_amount) > (SELECT AVG(v_spend) FROM (SELECT SUM(total_amount) AS v_spend FROM ingredient_purchases GROUP BY restaurant_id) sub) ORDER BY total_spend DESC;",'t',['Subquery computes average venue procurement spend.','HAVING clause filters venues above that average.'],'Flags high-spending culinary operations for budget review.',30,7),
  q('rest-L3-030','restaurants',3,30,'core','Purchases Count and Average by Supplier','Elena Rossi','Beverage & Cellar Director','For each supplier, how many purchase orders have been placed and what is their average order size?','JOIN suppliers with ingredient_purchases, COUNT and AVG.',['SELECT','INNER JOIN','COUNT','AVG','GROUP BY','ORDER BY'],['supplier_name','po_count','avg_po_amount'],"SELECT s.supplier_name, COUNT(ip.id) AS po_count, ROUND(AVG(ip.total_amount), 2) AS avg_po_amount FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id GROUP BY s.supplier_name ORDER BY po_count DESC;",'t',['Join suppliers with ingredient_purchases.','Aggregate COUNT(ip.id) and AVG(ip.total_amount).' ,'Group by supplier_name.'],'Evaluates supplier order frequency vs ticket size.',25,6),
  q('rest-L3-031','restaurants',3,31,'core','Most Expensive Dish in Each Category','Chef Marco Vieri','Executive Chef & Founder','Find the highest priced dish within each menu category: show category, dish name, and that peak price.','Correlated subquery or GROUP BY with MAX.',['SELECT','WHERE','Subquery'],['category','name','price'],"SELECT m.category, m.name, m.price FROM menu_items m WHERE m.price = (SELECT MAX(m2.price) FROM menu_items m2 WHERE m2.category = m.category) ORDER BY m.category, m.name;",'f',['Correlated subquery matches MAX(price) per category.','Outer query returns category, name, price.'],'Surfaces top-priced flagship dish for each category.',30,7),
  q('rest-L3-032','restaurants',3,32,'core','Restaurants With Seafood and Meat Orders','Chef Marco Vieri','Executive Chef & Founder','Which restaurants have purchased from both Meat AND Seafood suppliers? Show restaurant name and city.','INTERSECT or EXISTS matching both categories.',['SELECT','INTERSECT'],['restaurant_name','city'],"SELECT r.name AS restaurant_name, r.city FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id JOIN suppliers s ON ip.supplier_id = s.id WHERE s.category = 'Meat' INTERSECT SELECT r.name AS restaurant_name, r.city FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id JOIN suppliers s ON ip.supplier_id = s.id WHERE s.category = 'Seafood' ORDER BY restaurant_name;",'f',['Query restaurants buying Meat INTERSECT restaurants buying Seafood.','Order by restaurant_name.'],'Finds restaurants executing full surf-and-turf procurement.',30,7),
  q('rest-L3-033','restaurants',3,33,'core','Dishes Never Ordered in Pasta Category','Chef Marco Vieri','Executive Chef & Founder','Are there any pasta dishes that have literally never been ordered in any guest check?','NOT IN subquery on order_items filtered by pasta category.',['SELECT','WHERE','NOT IN'],['name'],"SELECT name FROM menu_items WHERE category = 'pasta' AND id NOT IN (SELECT DISTINCT menu_item_id FROM order_items) ORDER BY name;",'f',['Filter menu_items WHERE category = pasta.','Exclude items present in order_items via NOT IN subquery.'],'Identifies dead-weight pasta recipes for menu revision.',25,6),
  q('rest-L3-034','restaurants',3,34,'core','Cities With Multiple Restaurant Venues','Giulia Conti','Director of Hospitality','Which metropolitan cities host 2 or more of our restaurants? Show city name and the venue count.','GROUP BY city, HAVING COUNT(*) >= 2.',['SELECT','COUNT','GROUP BY','HAVING','ORDER BY'],['city','venue_count'],"SELECT city, COUNT(*) AS venue_count FROM restaurants GROUP BY city HAVING COUNT(*) >= 2 ORDER BY venue_count DESC, city ASC;",'t',['Group restaurants by city.','Filter HAVING COUNT(*) >= 2 and order by venue_count DESC.'],'Identifies cluster markets with multiple operating branches.',25,5),
  q('rest-L3-035','restaurants',3,35,'core','Ingredients With Stock Value Below Average','Chef Marco Vieri','Executive Chef & Founder','Which individual ingredients hold a total stock value (cost * qty) that is below the average stock value across all ingredients?','WHERE unit_cost * current_stock_qty < (SELECT AVG of total values).',['SELECT','WHERE','Subquery','Arithmetic','AVG'],['ingredient_name','stock_value'],"SELECT ingredient_name, ROUND(unit_cost * current_stock_qty, 2) AS stock_value FROM ingredients WHERE unit_cost * current_stock_qty < (SELECT AVG(unit_cost * current_stock_qty) FROM ingredients) ORDER BY stock_value ASC;",'t',['Subquery calculates AVG(unit_cost * current_stock_qty).','Outer query filters below average stock values.'],'Pins under-stocked or low-capital ingredients.',30,7),
  q('rest-L3-036','restaurants',3,36,'core','Orders Sourcing From Specific Servers','Giulia Conti','Director of Hospitality','Find total revenue and order count for server Marco V. compared to Luca B. using a single query.','Filter orders WHERE server_name IN, GROUP BY server_name.',['SELECT','WHERE','IN','COUNT','SUM','GROUP BY'],['server_name','order_count','total_sales'],"SELECT server_name, COUNT(*) AS order_count, SUM(total_amount) AS total_sales FROM orders WHERE server_name IN ('Marco V.', 'Luca B.') GROUP BY server_name ORDER BY total_sales DESC;",'t',['Filter WHERE server_name IN (Marco V., Luca B.).','Group by server_name with COUNT and SUM.'],'Direct head-to-head comparison of lead floor servers.',25,5),
  q('rest-L3-037','restaurants',3,37,'core','Dishes With Above Average Margin Percentage','Chef Marco Vieri','Executive Chef & Founder','Which dishes achieve a gross margin percentage higher than the company-wide average margin percentage?','(price - cost) / price > subquery avg.',['SELECT','WHERE','Subquery','Arithmetic'],['name','category','margin_pct'],"SELECT name, category, ROUND(((price - cost) / price) * 100, 1) AS margin_pct FROM menu_items WHERE ((price - cost) / price) > (SELECT AVG((price - cost) / price) FROM menu_items) ORDER BY margin_pct DESC;",'t',['Subquery computes average ((price - cost) / price).','Outer query filters items above this ratio.'],'Ranks premium margin contributors across the culinary menu.',30,7),
  q('rest-L3-038','restaurants',3,38,'core','Suppliers Not Used in April 2024','Elena Rossi','Beverage & Cellar Director','Identify any suppliers who have zero purchase orders recorded in April 2024.','Suppliers NOT IN purchase records for that date range.',['SELECT','WHERE','NOT IN'],['supplier_name','category'],"SELECT supplier_name, category FROM suppliers WHERE id NOT IN (SELECT DISTINCT supplier_id FROM ingredient_purchases WHERE purchase_date BETWEEN '2024-04-01' AND '2024-04-30') ORDER BY supplier_name;",'f',['Subquery finds suppliers active in April 2024.','Outer query checks NOT IN.'],'Finds idle suppliers during the monthly cycle.',25,6),
  q('rest-L3-039','restaurants',3,39,'core','Venues With High Capacity and High Spend','Giulia Conti','Director of Hospitality','Which restaurants have seating capacity > 150 AND total ingredient purchases over $5,000?','JOIN restaurants and ingredient_purchases, HAVING SUM > 5000 and capacity > 150.',['SELECT','INNER JOIN','WHERE','SUM','GROUP BY','HAVING'],['restaurant_name','seating_capacity','total_spend'],"SELECT r.name AS restaurant_name, r.seating_capacity, SUM(ip.total_amount) AS total_spend FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id WHERE r.seating_capacity > 150 GROUP BY r.name, r.seating_capacity HAVING SUM(ip.total_amount) > 5000 ORDER BY total_spend DESC;",'t',['Filter restaurants WHERE seating_capacity > 150.','Group by venue and filter HAVING SUM(ip.total_amount) > 5000.'],'Correlates physical venue scale with heavy purchasing volume.',30,7),
  q('rest-L3-040','restaurants',3,40,'core','Ingredients In Stock Below Reorder Threshold','Chef Marco Vieri','Executive Chef & Founder','List all ingredients where stock is lower than 150 units, displaying ingredient name, category, unit cost, and stock.','Filter ingredients WHERE current_stock_qty < 150.',['SELECT','WHERE'],['ingredient_name','category','unit_cost','current_stock_qty'],"SELECT ingredient_name, category, unit_cost, current_stock_qty FROM ingredients WHERE current_stock_qty < 150 ORDER BY current_stock_qty ASC;",'t',['Filter ingredients table with WHERE current_stock_qty < 150.','Order ascending to highlight the lowest stocks.'],'Operational restock triage list.',25,5),
  q('rest-L3-041','restaurants',3,41,'core','Suppliers With Highest Single Purchase Invoices','Elena Rossi','Beverage & Cellar Director','What was the largest single purchase amount made with each supplier? Supplier name and peak invoice amount.','JOIN suppliers with ingredient_purchases, MAX(total_amount).',['SELECT','INNER JOIN','MAX','GROUP BY','ORDER BY'],['supplier_name','max_single_purchase'],"SELECT s.supplier_name, MAX(ip.total_amount) AS max_single_purchase FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id GROUP BY s.supplier_name ORDER BY max_single_purchase DESC;",'t',['Join suppliers with ingredient_purchases.','Aggregate MAX(ip.total_amount) grouped by supplier_name.'],'Identifies maximum credit exposure per vendor.',25,6),
  q('rest-L3-042','restaurants',3,42,'core','Dishes Ordered More Than 5 Times With Cost > 10','Chef Marco Vieri','Executive Chef & Founder','Which dishes with food cost exceeding $10 have been ordered more than 5 times? Show dish name, cost, and times ordered.','JOIN order_items and menu_items, WHERE cost > 10, HAVING COUNT > 5.',['SELECT','INNER JOIN','WHERE','COUNT','GROUP BY','HAVING'],['name','cost','times_ordered'],"SELECT mi.name, mi.cost, COUNT(oi.id) AS times_ordered FROM menu_items mi JOIN order_items oi ON mi.id = oi.menu_item_id WHERE mi.cost > 10.00 GROUP BY mi.name, mi.cost HAVING COUNT(oi.id) > 5 ORDER BY times_ordered DESC;",'t',['Filter menu_items WHERE cost > 10.00.','Group by dish and filter HAVING COUNT(oi.id) > 5.'],'High-cost popular dishes needing tighter kitchen portion control.',30,7),
  q('rest-L3-043','restaurants',3,43,'core','Total Guest Covers by City','Giulia Conti','Director of Hospitality','How many total guest covers have booked reservations across each city? Show city and total covers.','JOIN reservations with restaurants, SUM(party_size) GROUP BY city.',['SELECT','INNER JOIN','SUM','GROUP BY','ORDER BY'],['city','total_covers'],"SELECT r.city, SUM(res.party_size) AS total_covers FROM restaurants r JOIN reservations res ON r.id = res.restaurant_id GROUP BY r.city ORDER BY total_covers DESC;",'t',['Join restaurants with reservations.','Group by city and calculate SUM(res.party_size).'],'Geographic breakdown of reservation patronage.',25,6),
  q('rest-L3-044','restaurants',3,44,'core','Categories Having More Than 4 Dishes','Chef Marco Vieri','Executive Chef & Founder','Which menu categories offer more than 4 distinct dishes? Show category name and dish count.','GROUP BY category on menu_items, HAVING COUNT(*) > 4.',['SELECT','COUNT','GROUP BY','HAVING','ORDER BY'],['category','dish_count'],"SELECT category, COUNT(*) AS dish_count FROM menu_items GROUP BY category HAVING COUNT(*) > 4 ORDER BY dish_count DESC;",'t',['Group menu_items by category.','Filter HAVING COUNT(*) > 4.'],'Checks menu depth across culinary categories.',25,5),
  q('rest-L3-045','restaurants',3,45,'core','Purchases by Restaurant in Boston or Chicago','Giulia Conti','Director of Hospitality','Pull all ingredient purchase lines for venues located in either Boston or Chicago with restaurant name and purchase date.','JOIN ingredient_purchases with restaurants WHERE city IN (Boston, Chicago).',['SELECT','INNER JOIN','WHERE','IN'],['restaurant_name','city','total_amount','purchase_date'],"SELECT r.name AS restaurant_name, r.city, ip.total_amount, ip.purchase_date FROM ingredient_purchases ip JOIN restaurants r ON ip.restaurant_id = r.id WHERE r.city IN ('Boston', 'Chicago') ORDER BY r.city, ip.total_amount DESC;",'f',['Join ingredient_purchases with restaurants.','Filter WHERE r.city IN (Boston, Chicago).'],'Regional procurement tracking for East and Midwest hubs.',25,6),
  q('rest-L3-046','restaurants',3,46,'core','Dishes With Cost Higher Than Average Cost in Same Category','Chef Marco Vieri','Executive Chef & Founder','Show each dish whose cost is strictly higher than the average cost of dishes within its own category.','Correlated subquery: cost > (SELECT AVG(cost) WHERE category = outer.category).',['SELECT','WHERE','Subquery','AVG'],['name','category','cost'],"SELECT m.name, m.category, m.cost FROM menu_items m WHERE m.cost > (SELECT AVG(m2.cost) FROM menu_items m2 WHERE m2.category = m.category) ORDER BY m.category, m.cost DESC;",'f',['Correlated subquery calculates AVG(cost) for m.category.','Filter outer row where cost exceeds category average.'],'Identifies cost outliers relative to peer category items.',30,7),
  q('rest-L3-047','restaurants',3,47,'core','Suppliers Providing Meat or Dry Goods With Rating >= 4.8','Elena Rossi','Beverage & Cellar Director','Which suppliers in Meat or Dry Goods maintain a rating of at least 4.8? Name, category, rating.','Filter suppliers WHERE category IN (Meat, Dry Goods) AND rating >= 4.8.',['SELECT','WHERE','IN','AND'],['supplier_name','category','rating'],"SELECT supplier_name, category, rating FROM suppliers WHERE category IN ('Meat', 'Dry Goods') AND rating >= 4.8 ORDER BY rating DESC, supplier_name;",'t',['Filter suppliers WHERE category IN (Meat, Dry Goods) AND rating >= 4.8.'],'High-reliability vendors in essential categories.',25,5),
  q('rest-L3-048','restaurants',3,48,'core','Difference Between Recorded and Theoretical Food Cost','Chef Marco Vieri','Executive Chef & Founder','For each dish, display name, selling price, food cost, and the food cost percentage (cost / price * 100).','SELECT name, price, cost, ROUND(cost / price * 100, 1) AS food_cost_pct.',['SELECT','Arithmetic'],['name','price','cost','food_cost_pct'],"SELECT name, price, cost, ROUND((cost / price) * 100, 1) AS food_cost_pct FROM menu_items ORDER BY food_cost_pct DESC;",'t',['Compute (cost / price) * 100 rounded to 1 decimal place.','Order descending by food cost percentage.'],'Menu engineering matrix: highlights high food-cost percentage dishes.',25,5),
  q('rest-L3-049','restaurants',3,49,'core','Venues With Above Average Seating Capacity','Giulia Conti','Director of Hospitality','List all restaurants whose seating capacity is strictly above the average seating capacity of all venues.','WHERE seating_capacity > (SELECT AVG(seating_capacity) FROM restaurants).',['SELECT','WHERE','Subquery','AVG'],['name','city','seating_capacity'],"SELECT name, city, seating_capacity FROM restaurants WHERE seating_capacity > (SELECT AVG(seating_capacity) FROM restaurants) ORDER BY seating_capacity DESC;",'t',['Subquery calculates AVG(seating_capacity) from restaurants.','Filter WHERE seating_capacity > subquery.'],'Identifies large-capacity dining halls.',25,6),
  q('rest-L3-050','restaurants',3,50,'core','Active Orders With Order Items Count','Giulia Conti','Director of Hospitality','For each order, display the order id, server name, order total, and the total count of item lines attached to it.','JOIN orders with order_items, GROUP BY order.',['SELECT','INNER JOIN','COUNT','GROUP BY','ORDER BY'],['order_id','server_name','total_amount','item_count'],"SELECT o.id AS order_id, o.server_name, o.total_amount, COUNT(oi.id) AS item_count FROM orders o JOIN order_items oi ON o.id = oi.order_id GROUP BY o.id, o.server_name, o.total_amount ORDER BY item_count DESC, o.total_amount DESC;",'t',['Join orders with order_items.','Group by order details and calculate COUNT(oi.id).' ],'Checks check density and item counts per dining ticket.',25,6),

  // CHALLENGING 51–75: Complex Subqueries, EXISTS, Set Ops, Cross-Table Reconciliations
  q('rest-L3-051','restaurants',3,51,'challenging','Venues With Purchases From All Categories','Elena Rossi','Beverage & Cellar Director','Find restaurants that have placed purchases with suppliers across at least 3 distinct categories.','JOIN restaurants, ingredient_purchases, suppliers. HAVING COUNT(DISTINCT s.category) >= 3.',['SELECT','INNER JOIN','COUNT DISTINCT','GROUP BY','HAVING'],['restaurant_name','distinct_categories'],"SELECT r.name AS restaurant_name, COUNT(DISTINCT s.category) AS distinct_categories FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id JOIN suppliers s ON ip.supplier_id = s.id GROUP BY r.name HAVING COUNT(DISTINCT s.category) >= 3 ORDER BY distinct_categories DESC, r.name;",'t',['Join restaurants, ingredient_purchases, and suppliers.','Group by restaurant and filter HAVING COUNT(DISTINCT s.category) >= 3.'],'Verifies diversified supply chain integration per venue.',30,8),
  q('rest-L3-052','restaurants',3,52,'challenging','Dishes Ordered More Than Any Dessert','Chef Marco Vieri','Executive Chef & Founder','Find all non-dessert dishes whose total units sold strictly exceed the units sold of the best-selling dessert.','WHERE category != dessert and total_sold > (SELECT MAX sold of desserts).',['SELECT','INNER JOIN','SUM','WHERE','GROUP BY','HAVING','Subquery'],['dish_name','total_sold'],"SELECT mi.name AS dish_name, SUM(oi.quantity) AS total_sold FROM menu_items mi JOIN order_items oi ON mi.id = oi.menu_item_id WHERE mi.category != 'dessert' GROUP BY mi.name HAVING SUM(oi.quantity) > (SELECT MAX(d_sales) FROM (SELECT SUM(oi2.quantity) AS d_sales FROM menu_items mi2 JOIN order_items oi2 ON mi2.id = oi2.menu_item_id WHERE mi2.category = 'dessert' GROUP BY mi2.id) sub) ORDER BY total_sold DESC;",'t',['Subquery finds maximum sales volume among desserts.','Outer query compares non-dessert dishes against this threshold.'],'Benchmarks mains and starters against peak dessert volume.',35,9),
  q('rest-L3-053','restaurants',3,53,'challenging','Supplier Market Share in Total Procurement','Elena Rossi','Beverage & Cellar Director','Calculate each supplier percentage share of total company procurement expenditure across all restaurants.','SUM(ip.total_amount) / (SELECT SUM(total_amount)) * 100.',['SELECT','INNER JOIN','SUM','Arithmetic','Subquery','GROUP BY'],['supplier_name','total_spent','spend_percentage'],"SELECT s.supplier_name, SUM(ip.total_amount) AS total_spent, ROUND((SUM(ip.total_amount) / (SELECT SUM(total_amount) FROM ingredient_purchases)) * 100, 2) AS spend_percentage FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id GROUP BY s.supplier_name ORDER BY total_spent DESC;",'t',['Join suppliers with ingredient_purchases.','Divide supplier spend by total company spend in subquery.'],'Evaluates vendor concentration and spend dominance.',35,8),
  q('rest-L3-054','restaurants',3,54,'challenging','Restaurants Operating at Zero Guest Complaints','Giulia Conti','Director of Hospitality','Which restaurants have received guest reviews but have NEVER received a rating below 4 stars?','EXISTS reviews AND NOT EXISTS review < 4.',['SELECT','WHERE','EXISTS','NOT EXISTS'],['restaurant_name','city'],"SELECT r.name AS restaurant_name, r.city FROM restaurants r WHERE EXISTS (SELECT 1 FROM guest_reviews gr WHERE gr.restaurant_id = r.id) AND NOT EXISTS (SELECT 1 FROM guest_reviews gr WHERE gr.restaurant_id = r.id AND gr.rating < 4) ORDER BY r.name;",'f',['Check EXISTS reviews for restaurant.','Check NOT EXISTS reviews with rating < 4.'],'Finds immaculate hospitality venues with zero sub-4 ratings.',35,8),
  q('rest-L3-055','restaurants',3,55,'challenging','Top Spending Venue For Each Supplier','Elena Rossi','Beverage & Cellar Director','For each supplier, identify the restaurant that has spent the most money with them.','Correlated subquery on restaurant spend per supplier.',['SELECT','INNER JOIN','GROUP BY','Subquery'],['supplier_name','restaurant_name','max_spend'],"SELECT s.supplier_name, r.name AS restaurant_name, SUM(ip.total_amount) AS max_spend FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id JOIN restaurants r ON ip.restaurant_id = r.id GROUP BY s.supplier_name, r.name HAVING SUM(ip.total_amount) = (SELECT MAX(v_spend) FROM (SELECT ip2.supplier_id, ip2.restaurant_id, SUM(ip2.total_amount) AS v_spend FROM ingredient_purchases ip2 GROUP BY ip2.supplier_id, ip2.restaurant_id) sub WHERE sub.supplier_id = s.id) ORDER BY s.supplier_name;",'f',['Group spend by supplier and restaurant.','Correlated subquery matches max spend for that supplier.'],'Identifies anchor account venues for each vendor.',35,10),
  q('rest-L3-056','restaurants',3,56,'challenging','High Cost Low Sales Dishes','Chef Marco Vieri','Executive Chef & Founder','Flag problematic menu items: dishes with cost > $10 whose total units sold are less than 10.','JOIN menu_items with order_items, WHERE cost > 10, HAVING SUM(quantity) < 10.',['SELECT','INNER JOIN','WHERE','SUM','GROUP BY','HAVING'],['dish_name','cost','total_units'],"SELECT mi.name AS dish_name, mi.cost, COALESCE(SUM(oi.quantity), 0) AS total_units FROM menu_items mi LEFT JOIN order_items oi ON mi.id = oi.menu_item_id WHERE mi.cost > 10.00 GROUP BY mi.name, mi.cost HAVING COALESCE(SUM(oi.quantity), 0) < 10 ORDER BY mi.cost DESC;",'t',['Left join menu_items with order_items.','Filter WHERE cost > 10.00 and HAVING total quantity < 10.'],'Highlights underperforming capital-heavy menu items.',30,8),
  q('rest-L3-057','restaurants',3,57,'challenging','Venues With Higher Spend Than Sales','Chef Marco Vieri','Executive Chef & Founder','Compare total procurement spend against total order revenue for each venue: show venues where spend exceeds $3,000.','JOIN restaurants with purchases SUM and orders SUM.',['SELECT','INNER JOIN','SUM','GROUP BY','HAVING'],['restaurant_name','procurement_spend'],"SELECT r.name AS restaurant_name, SUM(ip.total_amount) AS procurement_spend FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id GROUP BY r.name HAVING SUM(ip.total_amount) > 3000 ORDER BY procurement_spend DESC;",'t',['Group ingredient_purchases by restaurant.','Filter HAVING SUM(total_amount) > 3000.'],'Spots venues with elevated food procurement expenditure.',30,7),
  q('rest-L3-058','restaurants',3,58,'challenging','Dishes Ordered Together in Same Check','Chef Marco Vieri','Executive Chef & Founder','Find pairs of distinct dishes that were ordered together in the exact same order ticket at least twice.','Self join on order_items with menu_items.',['SELECT','INNER JOIN','COUNT','GROUP BY','HAVING'],['dish_1','dish_2','times_paired'],"SELECT m1.name AS dish_1, m2.name AS dish_2, COUNT(*) AS times_paired FROM order_items o1 JOIN order_items o2 ON o1.order_id = o2.order_id AND o1.menu_item_id < o2.menu_item_id JOIN menu_items m1 ON o1.menu_item_id = m1.id JOIN menu_items m2 ON o2.menu_item_id = m2.id GROUP BY m1.name, m2.name HAVING COUNT(*) >= 2 ORDER BY times_paired DESC, dish_1, dish_2;",'t',['Self-join order_items on order_id with o1.menu_item_id < o2.menu_item_id.','Join menu_items to resolve names.','Filter HAVING COUNT(*) >= 2.'],'Basket pairing analysis for combo meal promotions.',35,10),
  q('rest-L3-059','restaurants',3,59,'challenging','Unsold Ingredients Inventory Risk','Chef Marco Vieri','Executive Chef & Founder','List ingredients where current stock is greater than 150 AND unit cost is above $8, ordered by tied-up cash.','Filter ingredients where current_stock_qty > 150 AND unit_cost > 8.',['SELECT','WHERE','Arithmetic','ORDER BY'],['ingredient_name','category','unit_cost','current_stock_qty','cash_tied_up'],"SELECT ingredient_name, category, unit_cost, current_stock_qty, ROUND(unit_cost * current_stock_qty, 2) AS cash_tied_up FROM ingredients WHERE current_stock_qty > 150 AND unit_cost > 8.00 ORDER BY cash_tied_up DESC;",'t',['Filter ingredients table with stock > 150 and cost > 8.','Calculate unit_cost * current_stock_qty.'],'Surfaces high-capital exposure in raw food inventory.',30,6),
  q('rest-L3-060','restaurants',3,60,'challenging','Venues With Above Average Reviews and Bookings','Giulia Conti','Director of Hospitality','Which restaurants have both an above-average reservation count AND an above-average review count?','Subqueries comparing venue counts to company averages.',['SELECT','INNER JOIN','COUNT','GROUP BY','HAVING','Subquery'],['restaurant_name','reservation_count','review_count'],"SELECT r.name AS restaurant_name, COUNT(DISTINCT res.id) AS reservation_count, COUNT(DISTINCT gr.id) AS review_count FROM restaurants r LEFT JOIN reservations res ON r.id = res.restaurant_id LEFT JOIN guest_reviews gr ON r.id = gr.restaurant_id GROUP BY r.name HAVING COUNT(DISTINCT res.id) > (SELECT AVG(r_cnt) FROM (SELECT COUNT(id) AS r_cnt FROM reservations GROUP BY restaurant_id) s1) AND COUNT(DISTINCT gr.id) > (SELECT AVG(g_cnt) FROM (SELECT COUNT(id) AS g_cnt FROM guest_reviews GROUP BY restaurant_id) s2) ORDER BY reservation_count DESC;",'t',['Calculate reservation and review counts per restaurant.','HAVING clause checks both against subquery averages.'],'Identifies star operating units firing on all cylinders.',35,10),
  q('rest-L3-061','restaurants',3,61,'challenging','Most Frequent Server For Large Parties','Giulia Conti','Director of Hospitality','Which server has handled the highest number of large parties (reservations with party size >= 6)?','Count reservations >= 6 grouped by server or table.',['SELECT','COUNT','GROUP BY','ORDER BY','LIMIT'],['party_size','booking_count'],"SELECT party_size, COUNT(*) AS booking_count FROM reservations WHERE party_size >= 6 GROUP BY party_size ORDER BY booking_count DESC;",'t',['Filter reservations WHERE party_size >= 6.','Group by party_size and count.'],'Analyzes volume of banquets and group bookings.',25,5),
  q('rest-L3-062','restaurants',3,62,'challenging','Purchases Over Vendor Average Amount','Elena Rossi','Beverage & Cellar Director','List individual purchase invoices where the invoice total exceeds that vendor average invoice amount.','Correlated subquery: total_amount > (SELECT AVG for same supplier).',['SELECT','INNER JOIN','WHERE','Subquery','AVG'],['supplier_name','total_amount','purchase_date'],"SELECT s.supplier_name, ip.total_amount, ip.purchase_date FROM ingredient_purchases ip JOIN suppliers s ON ip.supplier_id = s.id WHERE ip.total_amount > (SELECT AVG(ip2.total_amount) FROM ingredient_purchases ip2 WHERE ip2.supplier_id = ip.supplier_id) ORDER BY s.supplier_name, ip.total_amount DESC;",'f',['Correlated subquery computes AVG(total_amount) for that supplier_id.','Filter where purchase exceeds supplier average.'],'Spots unusually large purchase tickets.',35,9),
  q('rest-L3-063','restaurants',3,63,'challenging','Cities Where All Venues Are Post 2018','Chef Marco Vieri','Executive Chef & Founder','Find all cities where EVERY operating restaurant was opened in 2018 or later.','GROUP BY city, HAVING MIN(opened_year) >= 2018.',['SELECT','MIN','GROUP BY','HAVING'],['city','oldest_venue_year'],"SELECT city, MIN(opened_year) AS oldest_venue_year FROM restaurants GROUP BY city HAVING MIN(opened_year) >= 2018 ORDER BY city;",'f',['Group by city and calculate MIN(opened_year).','Filter HAVING MIN(opened_year) >= 2018.'],'Finds modern, newly established regional clusters.',30,6),
  q('rest-L3-064','restaurants',3,64,'challenging','Average Guest Rating vs Seating Capacity Quartiles','Chef Marco Vieri','Executive Chef & Founder','Compare the average guest rating for small venues (<=120 seats) vs large venues (>120 seats).','CASE WHEN on seating_capacity with AVG(gr.rating).',['SELECT','AVG','CASE WHEN','GROUP BY'],['venue_size_tier','avg_rating'],"SELECT CASE WHEN r.seating_capacity <= 120 THEN 'Boutique (<=120)' ELSE 'Grand (>120)' END AS venue_size_tier, ROUND(AVG(gr.rating), 2) AS avg_rating FROM restaurants r JOIN guest_reviews gr ON r.id = gr.restaurant_id GROUP BY CASE WHEN r.seating_capacity <= 120 THEN 'Boutique (<=120)' ELSE 'Grand (>120)' END ORDER BY avg_rating DESC;",'t',['Use CASE WHEN to categorize venue scale.','Compute AVG(rating) for each tier.'],'Hospitality study: does boutique scale drive higher guest satisfaction?',30,7),
  q('rest-L3-065','restaurants',3,65,'challenging','Highest Margin Dish in Each Category','Chef Marco Vieri','Executive Chef & Founder','For each menu category, return the dish that achieves the highest gross profit dollar margin (price - cost).','Correlated subquery finding MAX(price - cost) per category.',['SELECT','WHERE','Subquery'],['category','name','max_unit_margin'],"SELECT m.category, m.name, ROUND(m.price - m.cost, 2) AS max_unit_margin FROM menu_items m WHERE (m.price - m.cost) = (SELECT MAX(m2.price - m2.cost) FROM menu_items m2 WHERE m2.category = m.category) ORDER BY m.category;",'f',['Correlated subquery calculates MAX(price - cost) for each category.','Outer query returns category, name, margin.'],'Pins the primary profit anchor for each kitchen station.',35,9),
  q('rest-L3-066','restaurants',3,66,'challenging','Suppliers With Invoices in Multiple Months','Elena Rossi','Beverage & Cellar Director','Which suppliers have purchase records spanning more than 1 distinct calendar month?','GROUP BY supplier, HAVING COUNT(DISTINCT EXTRACT(MONTH)).',['SELECT','INNER JOIN','COUNT DISTINCT','GROUP BY','HAVING'],['supplier_name','active_months'],"SELECT s.supplier_name, COUNT(DISTINCT EXTRACT(MONTH FROM ip.purchase_date)) AS active_months FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id GROUP BY s.supplier_name ORDER BY active_months DESC, s.supplier_name;",'f',['Extract month from purchase_date.','Count distinct months per supplier.'],'Checks supplier persistence across reporting periods.',30,7),
  q('rest-L3-067','restaurants',3,67,'challenging','Orders Containing Both Food and Wine','Elena Rossi','Beverage & Cellar Director','Find all order IDs that include at least one food entree AND at least one beverage item.','INTERSECT or EXISTS matching both categories for order_id.',['SELECT','INNER JOIN','WHERE','INTERSECT'],['order_id'],"SELECT oi.order_id FROM order_items oi JOIN menu_items mi ON oi.menu_item_id = mi.id WHERE mi.category = 'entree' INTERSECT SELECT oi.order_id FROM order_items oi JOIN menu_items mi ON oi.menu_item_id = mi.id WHERE mi.category = 'beverage' ORDER BY order_id;",'f',['Query orders with entree INTERSECT orders with beverage.'],'Evaluates beverage attachment rate on dining checks.',35,8),
  q('rest-L3-068','restaurants',3,68,'challenging','Total Spent on Dairy vs Produce Ingredients','Chef Marco Vieri','Executive Chef & Founder','Calculate total inventory value on hand for Dairy vs Produce side-by-side using CASE WHEN aggregation.','SUM(CASE WHEN) for Dairy and Produce stock value.',['SELECT','SUM','CASE WHEN','Arithmetic'],['dairy_value','produce_value'],"SELECT ROUND(SUM(CASE WHEN category = 'Dairy' THEN unit_cost * current_stock_qty ELSE 0 END), 2) AS dairy_value, ROUND(SUM(CASE WHEN category = 'Produce' THEN unit_cost * current_stock_qty ELSE 0 END), 2) AS produce_value FROM ingredients;",'f',['Use CASE WHEN inside SUM to isolate Dairy and Produce inventory value.'],'Pivots pantry valuation across perishable groups.',30,6),
  q('rest-L3-069','restaurants',3,69,'challenging','Confirmed Reservations Share by Venue','Giulia Conti','Director of Hospitality','For each restaurant, what percentage of all reservations are confirmed bookings? Minimum 3 reservations.','SUM(CASE WHEN status = confirmed) / COUNT(*) * 100.',['SELECT','INNER JOIN','COUNT','SUM','CASE WHEN','GROUP BY','HAVING'],['restaurant_name','total_bookings','confirmation_pct'],"SELECT r.name AS restaurant_name, COUNT(res.id) AS total_bookings, ROUND((SUM(CASE WHEN res.status = 'confirmed' THEN 1 ELSE 0 END)::NUMERIC / COUNT(res.id)) * 100, 1) AS confirmation_pct FROM restaurants r JOIN reservations res ON r.id = res.restaurant_id GROUP BY r.name HAVING COUNT(res.id) >= 3 ORDER BY confirmation_pct DESC;",'t',['Join restaurants with reservations.','Compute confirmation percentage using conditional SUM over COUNT.'],'Measures front-of-house booking conversion quality.',35,8),
  q('rest-L3-070','restaurants',3,70,'challenging','Venues With Largest Reservation Volume','Giulia Conti','Director of Hospitality','Top 3 restaurants by total booked covers with their opening year and city.','JOIN restaurants with reservations, SUM(party_size) LIMIT 3.',['SELECT','INNER JOIN','SUM','GROUP BY','ORDER BY','LIMIT'],['restaurant_name','city','opened_year','total_covers'],"SELECT r.name AS restaurant_name, r.city, r.opened_year, SUM(res.party_size) AS total_covers FROM restaurants r JOIN reservations res ON r.id = res.restaurant_id GROUP BY r.name, r.city, r.opened_year ORDER BY total_covers DESC LIMIT 3;",'t',['Join restaurants with reservations.','Group by venue and order by SUM(party_size) DESC LIMIT 3.'],'Ranks podium venues by guest cover throughput.',25,5),
  q('rest-L3-071','restaurants',3,71,'challenging','Supplier Ranking by Average Spend Per Order','Elena Rossi','Beverage & Cellar Director','Rank our suppliers by average invoice ticket size, showing supplier name, category, and average amount.','JOIN suppliers with ingredient_purchases, AVG(total_amount).',['SELECT','INNER JOIN','AVG','GROUP BY','ORDER BY'],['supplier_name','category','avg_spend'],"SELECT s.supplier_name, s.category, ROUND(AVG(ip.total_amount), 2) AS avg_spend FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id GROUP BY s.supplier_name, s.category ORDER BY avg_spend DESC;",'t',['Join suppliers with ingredient_purchases.','Aggregate AVG(total_amount) grouped by supplier_name, category.'],'Highlights vendor purchasing scale per order.',25,6),
  q('rest-L3-072','restaurants',3,72,'challenging','Dishes Accounting for Over 15% of Category Revenue','Chef Marco Vieri','Executive Chef & Founder','Find any dish whose revenue makes up more than 15% of its category total revenue.','Correlated subquery comparing dish revenue to category revenue.',['SELECT','INNER JOIN','SUM','Arithmetic','GROUP BY','HAVING','Subquery'],['dish_name','category','dish_revenue'],"SELECT mi.name AS dish_name, mi.category, SUM(oi.quantity * mi.price) AS dish_revenue FROM menu_items mi JOIN order_items oi ON mi.id = oi.menu_item_id GROUP BY mi.name, mi.category HAVING SUM(oi.quantity * mi.price) > 0.15 * (SELECT SUM(oi2.quantity * mi2.price) FROM menu_items mi2 JOIN order_items oi2 ON mi2.id = oi2.menu_item_id WHERE mi2.category = mi.category) ORDER BY dish_revenue DESC;",'t',['Calculate dish revenue with SUM(quantity * price).','HAVING checks against 0.15 * category revenue subquery.'],'Identifies dominant menu stars within each culinary section.',35,10),
  q('rest-L3-073','restaurants',3,73,'challenging','Restaurants Sourcing Exclusively High Rated Suppliers','Chef Marco Vieri','Executive Chef & Founder','Find restaurants where every single supplier they buy from has a rating of 4.8 or higher.','NOT EXISTS supplier with rating < 4.8.',['SELECT','INNER JOIN','WHERE','NOT EXISTS'],['restaurant_name','city'],"SELECT DISTINCT r.name AS restaurant_name, r.city FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id WHERE NOT EXISTS (SELECT 1 FROM ingredient_purchases ip2 JOIN suppliers s ON ip2.supplier_id = s.id WHERE ip2.restaurant_id = r.id AND s.rating < 4.8) ORDER BY r.name;",'f',['Check NOT EXISTS purchase where supplier rating < 4.8.','Ensures rigorous quality compliance across all vendor relationships.'],'Identifies venues maintaining strict tier-1 vendor standards.',35,9),
  q('rest-L3-074','restaurants',3,74,'challenging','Pantry Stock Turnover Warning','Chef Marco Vieri','Executive Chef & Founder','Identify ingredients where unit cost is under $5.00 but current stock is over 300 units — potential overstocking.','Filter ingredients WHERE unit_cost < 5.00 AND current_stock_qty > 300.',['SELECT','WHERE','AND'],['ingredient_name','category','unit_cost','current_stock_qty'],"SELECT ingredient_name, category, unit_cost, current_stock_qty FROM ingredients WHERE unit_cost < 5.00 AND current_stock_qty > 300 ORDER BY current_stock_qty DESC;",'t',['Filter ingredients table with unit_cost < 5.00 and current_stock_qty > 300.'],'Flags overstocked low-cost goods taking up shelf volume.',25,5),
  q('rest-L3-075','restaurants',3,75,'challenging','Venues With Multiple Dining Sections','Giulia Conti','Director of Hospitality','List all restaurants that have 2 or more distinct dining sections, showing venue name, city, and section count.','JOIN restaurants with dining_sections, GROUP BY restaurant, HAVING COUNT >= 2.',['SELECT','INNER JOIN','COUNT','GROUP BY','HAVING','ORDER BY'],['restaurant_name','city','section_count'],"SELECT r.name AS restaurant_name, r.city, COUNT(ds.id) AS section_count FROM restaurants r JOIN dining_sections ds ON r.id = ds.restaurant_id GROUP BY r.name, r.city HAVING COUNT(ds.id) >= 2 ORDER BY section_count DESC, r.name;",'t',['Join restaurants with dining_sections.','Group by venue and filter HAVING COUNT(ds.id) >= 2.'],'Finds complex multi-zone dining environments.',30,6),

  // BOSS 76–100: Executive P&L, Comprehensive Supply Chain Audits & Cross-Entity Analytics
  q('rest-L3-076','restaurants',3,76,'boss','Executive Procurement P&L Overview','Chef Marco Vieri','Executive Chef & Founder','Executive overview: total supplier invoices, total spend, average spend per invoice, and highest single invoice amount.','Aggregate ingredient_purchases: COUNT, SUM, AVG, MAX.',['SELECT','COUNT','SUM','AVG','MAX'],['total_invoices','total_procurement_spend','avg_invoice_size','largest_single_invoice'],"SELECT COUNT(*) AS total_invoices, ROUND(SUM(total_amount), 2) AS total_procurement_spend, ROUND(AVG(total_amount), 2) AS avg_invoice_size, MAX(total_amount) AS largest_single_invoice FROM ingredient_purchases;",'f',['Aggregate ingredient_purchases table for corporate P&L summary.'],'Corporate board procurement expenditure card.',35,8),
  q('rest-L3-077','restaurants',3,77,'boss','Supplier Scorecard With Performance Tiers','Elena Rossi','Beverage & Cellar Director','Complete supplier scorecard: name, category, rating, order count, total revenue received, and tier label based on spend.','JOIN suppliers with purchases, CASE WHEN on total spend for tier.',['SELECT','INNER JOIN','COUNT','SUM','CASE WHEN','GROUP BY','ORDER BY'],['supplier_name','category','rating','order_count','total_spend','partner_tier'],"SELECT s.supplier_name, s.category, s.rating, COUNT(ip.id) AS order_count, SUM(ip.total_amount) AS total_spend, CASE WHEN SUM(ip.total_amount) >= 25000 THEN 'Strategic Platinum' WHEN SUM(ip.total_amount) >= 15000 THEN 'Preferred Gold' ELSE 'Standard Silver' END AS partner_tier FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id GROUP BY s.supplier_name, s.category, s.rating ORDER BY total_spend DESC;",'t',['Join suppliers with ingredient_purchases.','Aggregate spend and classify into Strategic, Preferred, Standard tiers.'],'Comprehensive supplier relationship tiering system.',40,10),
  q('rest-L3-078','restaurants',3,78,'boss','Venue Efficiency: Revenue vs Purchasing Ratio','Chef Marco Vieri','Executive Chef & Founder','For each venue that has recorded purchases, compute total procurement spend and total tables available.','JOIN restaurants with ingredient_purchases and dining_tables.',['SELECT','INNER JOIN','COUNT DISTINCT','SUM','GROUP BY','ORDER BY'],['restaurant_name','city','table_count','total_procurement'],"SELECT r.name AS restaurant_name, r.city, COUNT(DISTINCT dt.id) AS table_count, SUM(ip.total_amount) AS total_procurement FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id LEFT JOIN dining_tables dt ON r.id = dt.restaurant_id GROUP BY r.name, r.city ORDER BY total_procurement DESC;",'t',['Join restaurants with ingredient_purchases and dining_tables.','Group by venue and compute table count alongside procurement spend.'],'Operational capacity vs procurement capital allocation.',40,10),
  q('rest-L3-079','restaurants',3,79,'boss','Full Inventory Valuation and Risk Audit','Chef Marco Vieri','Executive Chef & Founder','Complete inventory audit: total items tracked, total valuation, count of items below 100 units, and count of items above $10 cost.','COUNT, SUM, and conditional SUMs on ingredients.',['SELECT','COUNT','SUM','CASE WHEN','Arithmetic'],['total_ingredients','total_valuation','low_stock_items','premium_cost_items'],"SELECT COUNT(*) AS total_ingredients, ROUND(SUM(unit_cost * current_stock_qty), 2) AS total_valuation, SUM(CASE WHEN current_stock_qty < 100 THEN 1 ELSE 0 END) AS low_stock_items, SUM(CASE WHEN unit_cost >= 10.00 THEN 1 ELSE 0 END) AS premium_cost_items FROM ingredients;",'f',['Full-table aggregate on ingredients with conditional sums for KPI tracking.'],'Balance sheet inventory risk scorecard.',35,8),
  q('rest-L3-080','restaurants',3,80,'boss','Dish Contribution Margin and Volume Leaderboard','Chef Marco Vieri','Executive Chef & Founder','For all dishes ordered at least 3 times: dish name, category, total units sold, gross revenue, food cost, and net gross profit.','JOIN menu_items with order_items, multiple SUMs, HAVING COUNT >= 3.',['SELECT','INNER JOIN','SUM','Arithmetic','GROUP BY','HAVING','ORDER BY'],['name','category','units_sold','gross_revenue','total_food_cost','net_gross_profit'],"SELECT mi.name, mi.category, SUM(oi.quantity) AS units_sold, ROUND(SUM(oi.quantity * mi.price), 2) AS gross_revenue, ROUND(SUM(oi.quantity * mi.cost), 2) AS total_food_cost, ROUND(SUM(oi.quantity * (mi.price - mi.cost)), 2) AS net_gross_profit FROM menu_items mi JOIN order_items oi ON mi.id = oi.menu_item_id GROUP BY mi.name, mi.category HAVING SUM(oi.quantity) >= 3 ORDER BY net_gross_profit DESC;",'t',['Join menu_items with order_items.','Compute revenue, food cost, and profit aggregates with volume filter.'],'Executive dish profitability and contribution matrix.',40,10),
  q('rest-L3-081','restaurants',3,81,'boss','Top Performing Restaurant in Each Metro Area','Giulia Conti','Director of Hospitality','For each city with reviews, identify the single restaurant with the highest average rating.','Correlated subquery finding MAX avg rating per city.',['SELECT','INNER JOIN','AVG','GROUP BY','Subquery'],['city','restaurant_name','best_rating'],"SELECT r.city, r.name AS restaurant_name, ROUND(AVG(gr.rating), 2) AS best_rating FROM restaurants r JOIN guest_reviews gr ON r.id = gr.restaurant_id GROUP BY r.city, r.name HAVING AVG(gr.rating) = (SELECT MAX(sub.avg_r) FROM (SELECT r2.city, r2.name, AVG(gr2.rating) AS avg_r FROM restaurants r2 JOIN guest_reviews gr2 ON r2.id = gr2.restaurant_id GROUP BY r2.city, r2.name) sub WHERE sub.city = r.city) ORDER BY r.city;",'f',['Group by city and venue.','Correlated subquery identifies top rating per metro market.'],'Metropolitan flagship recognition report.',40,12),
  q('rest-L3-082','restaurants',3,82,'boss','Pantry Category Balance: High vs Low Volume Categories','Chef Marco Vieri','Executive Chef & Founder','Pantry category summary: category name, number of ingredients, average unit cost, total stock on hand, and total holding value.','GROUP BY category on ingredients table with multiple aggregates.',['SELECT','COUNT','AVG','SUM','Arithmetic','GROUP BY','ORDER BY'],['category','ingredient_count','avg_unit_cost','total_stock_units','total_holding_value'],"SELECT category, COUNT(*) AS ingredient_count, ROUND(AVG(unit_cost), 2) AS avg_unit_cost, ROUND(SUM(current_stock_qty), 2) AS total_stock_units, ROUND(SUM(unit_cost * current_stock_qty), 2) AS total_holding_value FROM ingredients GROUP BY category ORDER BY total_holding_value DESC;",'t',['Group ingredients by category.','Compute item count, avg unit cost, total units, and total value.'],'Category-level inventory balance assessment.',35,8),
  q('rest-L3-083','restaurants',3,83,'boss','Server Sales Mix: Appetizer vs Entree Ratio','Giulia Conti','Director of Hospitality','For each server, calculate total sales from appetizers vs total sales from entrees.','3-way JOIN orders, order_items, menu_items with CASE WHEN aggregation.',['SELECT','INNER JOIN','SUM','CASE WHEN','GROUP BY','ORDER BY'],['server_name','appetizer_sales','entree_sales'],"SELECT o.server_name, ROUND(SUM(CASE WHEN mi.category = 'appetizer' THEN oi.quantity * mi.price ELSE 0 END), 2) AS appetizer_sales, ROUND(SUM(CASE WHEN mi.category = 'entree' THEN oi.quantity * mi.price ELSE 0 END), 2) AS entree_sales FROM orders o JOIN order_items oi ON o.id = oi.order_id JOIN menu_items mi ON oi.menu_item_id = mi.id GROUP BY o.server_name ORDER BY entree_sales DESC;",'t',['Join orders, order_items, menu_items.','Use CASE WHEN inside SUM to separate sales by category per server.'],'Evaluates server upselling effectiveness on starters vs mains.',40,10),
  q('rest-L3-084','restaurants',3,84,'boss','Supply Chain Dependency on Single Vendor','Elena Rossi','Beverage & Cellar Director','Find restaurants where over 50% of their total procurement spend went to a single supplier.','Subquery comparing supplier spend per venue to total venue spend.',['SELECT','INNER JOIN','SUM','Arithmetic','GROUP BY','HAVING','Subquery'],['restaurant_name','supplier_name','vendor_spend','venue_total_spend'],"SELECT r.name AS restaurant_name, s.supplier_name, SUM(ip.total_amount) AS vendor_spend, (SELECT SUM(ip2.total_amount) FROM ingredient_purchases ip2 WHERE ip2.restaurant_id = r.id) AS venue_total_spend FROM restaurants r JOIN ingredient_purchases ip ON r.id = ip.restaurant_id JOIN suppliers s ON ip.supplier_id = s.id GROUP BY r.id, r.name, s.supplier_name HAVING SUM(ip.total_amount) > 0.50 * (SELECT SUM(ip2.total_amount) FROM ingredient_purchases ip2 WHERE ip2.restaurant_id = r.id) ORDER BY vendor_spend DESC;",'t',['Group by venue and supplier.','Filter HAVING vendor spend > 50% of venue total spend.'],'Critical supply chain single-point-of-failure risk analysis.',45,12),
  q('rest-L3-085','restaurants',3,85,'boss','Venues With High Capacity but Below Average Covers','Giulia Conti','Director of Hospitality','Spot underutilized venues: restaurants with seating capacity > 140 whose total booked covers are below average.','WHERE seating_capacity > 140 AND SUM(party_size) < subquery avg.',['SELECT','INNER JOIN','SUM','GROUP BY','HAVING','Subquery'],['restaurant_name','seating_capacity','total_covers'],"SELECT r.name AS restaurant_name, r.seating_capacity, SUM(res.party_size) AS total_covers FROM restaurants r JOIN reservations res ON r.id = res.restaurant_id WHERE r.seating_capacity > 140 GROUP BY r.name, r.seating_capacity HAVING SUM(res.party_size) < (SELECT AVG(covers) FROM (SELECT SUM(party_size) AS covers FROM reservations GROUP BY restaurant_id) sub) ORDER BY r.seating_capacity DESC;",'t',['Filter venues with seating_capacity > 140.','HAVING clause checks total covers against subquery average.'],'Pinpoints underperforming large-scale venues for marketing pushes.',40,10),
  q('rest-L3-086','restaurants',3,86,'boss','Most Profitable Dining Table Number Across Network','Giulia Conti','Director of Hospitality','Across all venues, which table numbers have generated the highest cumulative order billings? Top 5 table numbers.','GROUP BY table_number on orders, SUM(total_amount) LIMIT 5.',['SELECT','SUM','COUNT','GROUP BY','ORDER BY','LIMIT'],['table_number','total_revenue','checks_served'],"SELECT table_number, ROUND(SUM(total_amount), 2) AS total_revenue, COUNT(*) AS checks_served FROM orders GROUP BY table_number ORDER BY total_revenue DESC LIMIT 5;",'t',['Group orders by table_number.','Sum total_amount and count checks. Order DESC LIMIT 5.'],'Identifies most lucrative floor table placements.',30,6),
  q('rest-L3-087','restaurants',3,87,'boss','Suppliers Fulfilling Across All Regions','Elena Rossi','Beverage & Cellar Director','Find suppliers who have fulfilled purchase orders for restaurants in at least 5 different cities.','JOIN suppliers, ingredient_purchases, restaurants. HAVING COUNT(DISTINCT r.city) >= 5.',['SELECT','INNER JOIN','COUNT DISTINCT','GROUP BY','HAVING'],['supplier_name','cities_served'],"SELECT s.supplier_name, COUNT(DISTINCT r.city) AS cities_served FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id JOIN restaurants r ON ip.restaurant_id = r.id GROUP BY s.supplier_name HAVING COUNT(DISTINCT r.city) >= 5 ORDER BY cities_served DESC, s.supplier_name;",'f',['Join suppliers, ingredient_purchases, and restaurants.','Group by supplier and filter HAVING COUNT(DISTINCT city) >= 5.'],'Verifies national distribution reach for core partners.',35,8),
  q('rest-L3-088','restaurants',3,88,'boss','Menu Cannibalization: Similar Items Sales Gap','Chef Marco Vieri','Executive Chef & Founder','Compare sales between our two top pasta dishes: Truffle Tagliatelle and Fettuccine Al Ragu.','Filter menu_items by names, compute units sold and revenue side-by-side.',['SELECT','INNER JOIN','WHERE','IN','SUM','GROUP BY'],['name','units_sold','total_revenue'],"SELECT mi.name, SUM(oi.quantity) AS units_sold, ROUND(SUM(oi.quantity * mi.price), 2) AS total_revenue FROM menu_items mi JOIN order_items oi ON mi.id = oi.menu_item_id WHERE mi.name IN ('Truffle Tagliatelle', 'Fettuccine Al Ragu') GROUP BY mi.name ORDER BY total_revenue DESC;",'t',['Filter menu items WHERE name IN (Truffle Tagliatelle, Fettuccine Al Ragu).','Compute units sold and total revenue per dish.'],'Direct head-to-head pasta category cannibalization analysis.',30,7),
  q('rest-L3-089','restaurants',3,89,'boss','Composite Venue Performance Scorecard','Giulia Conti','Director of Hospitality','Comprehensive venue scorecard: restaurant name, seating capacity, total reservations, confirmed count, and review average.','LEFT JOIN restaurants with reservations and guest_reviews with conditional aggregates.',['SELECT','LEFT JOIN','COUNT DISTINCT','SUM','AVG','CASE WHEN','GROUP BY','ORDER BY'],['restaurant_name','seating_capacity','total_reservations','confirmed_reservations','avg_rating'],"SELECT r.name AS restaurant_name, r.seating_capacity, COUNT(DISTINCT res.id) AS total_reservations, SUM(CASE WHEN res.status = 'confirmed' THEN 1 ELSE 0 END) AS confirmed_reservations, ROUND(AVG(gr.rating), 2) AS avg_rating FROM restaurants r LEFT JOIN reservations res ON r.id = res.restaurant_id LEFT JOIN guest_reviews gr ON r.id = gr.restaurant_id GROUP BY r.name, r.seating_capacity ORDER BY avg_rating DESC NULLS LAST, total_reservations DESC;",'f',['Multi-table LEFT JOIN combining reservations and guest reviews per restaurant.'],'Full 360-degree venue operations and guest sentiment scorecard.',45,12),
  q('rest-L3-090','restaurants',3,90,'boss','Cost Inefficiency: Dishes Priced Near Food Cost','Chef Marco Vieri','Executive Chef & Founder','Audit pricing safety: find any dishes where the food cost is greater than 40% of the retail selling price.','Filter menu_items WHERE (cost / price) > 0.40.',['SELECT','WHERE','Arithmetic'],['name','category','price','cost','cost_ratio'],"SELECT name, category, price, cost, ROUND((cost / price) * 100, 1) AS cost_ratio FROM menu_items WHERE (cost / price) > 0.40 ORDER BY cost_ratio DESC;",'t',['Filter menu_items WHERE (cost / price) > 0.40.','Display retail price, food cost, and cost ratio percentage.'],'Red-flag audit for dishes threatening kitchen margin thresholds.',30,6),
  q('rest-L3-091','restaurants',3,91,'boss','Venues Generating Highest Beverage Margin Dollar','Elena Rossi','Beverage & Cellar Director','Calculate total beverage gross profit generated per order across all orders that included drinks.','3-way JOIN orders, order_items, menu_items WHERE category = beverage.',['SELECT','INNER JOIN','WHERE','SUM','Arithmetic','GROUP BY','ORDER BY'],['order_id','server_name','beverage_profit'],"SELECT o.id AS order_id, o.server_name, ROUND(SUM(oi.quantity * (mi.price - mi.cost)), 2) AS beverage_profit FROM orders o JOIN order_items oi ON o.id = oi.order_id JOIN menu_items mi ON oi.menu_item_id = mi.id WHERE mi.category = 'beverage' GROUP BY o.id, o.server_name ORDER BY beverage_profit DESC LIMIT 10;",'t',['Join orders, order_items, menu_items where category = beverage.','Calculate SUM(oi.quantity * (mi.price - mi.cost)) grouped by order.'],'Identifies top cellar-driven guest tickets.',35,8),
  q('rest-L3-092','restaurants',3,92,'boss','Cities With Zero Guest Complaints Recorded','Giulia Conti','Director of Hospitality','Find cities where every recorded guest review across all restaurants in that city has a rating of 5 stars.','GROUP BY city, HAVING MIN(gr.rating) = 5.',['SELECT','INNER JOIN','MIN','GROUP BY','HAVING'],['city'],"SELECT r.city FROM restaurants r JOIN guest_reviews gr ON r.id = gr.restaurant_id GROUP BY r.city HAVING MIN(gr.rating) = 5 ORDER BY r.city;",'f',['Join restaurants with guest_reviews.','Group by city and filter HAVING MIN(gr.rating) = 5.'],'Pinpoints metropolitan regions delivering flaw-free experiences.',35,8),
  q('rest-L3-093','restaurants',3,93,'boss','Cumulative Supply Spend by Month and Category','Elena Rossi','Beverage & Cellar Director','Monthly procurement trends: extract year and month from purchase_date, showing spend per supplier category.','GROUP BY EXTRACT(YEAR), EXTRACT(MONTH), s.category.',['SELECT','INNER JOIN','SUM','GROUP BY','ORDER BY'],['purchase_year','purchase_month','category','monthly_spend'],"SELECT EXTRACT(YEAR FROM ip.purchase_date)::INT AS purchase_year, EXTRACT(MONTH FROM ip.purchase_date)::INT AS purchase_month, s.category, ROUND(SUM(ip.total_amount), 2) AS monthly_spend FROM ingredient_purchases ip JOIN suppliers s ON ip.supplier_id = s.id GROUP BY EXTRACT(YEAR FROM ip.purchase_date), EXTRACT(MONTH FROM ip.purchase_date), s.category ORDER BY purchase_year, purchase_month, monthly_spend DESC;",'t',['Extract year and month from purchase_date.','Group with supplier category and compute SUM(total_amount).'],'Monthly budget tracking by procurement supply segment.',35,9),
  q('rest-L3-094','restaurants',3,94,'boss','Average Check Size for Parties Above 4','Giulia Conti','Director of Hospitality','What is the average party size and total guest count for confirmed group reservations of 5 or more people?','AVG(party_size) and SUM(party_size) WHERE status = confirmed AND party_size >= 5.',['SELECT','AVG','SUM','WHERE','AND'],['avg_group_size','total_group_guests'],"SELECT ROUND(AVG(party_size), 1) AS avg_group_size, SUM(party_size) AS total_group_guests FROM reservations WHERE status = 'confirmed' AND party_size >= 5;",'f',['Filter reservations WHERE status = confirmed AND party_size >= 5.','Compute AVG and SUM of party_size.'],'Capacity modeling for large banquet sections.',25,5),
  q('rest-L3-095','restaurants',3,95,'boss','Inventory Replacement Cost by Supplier Category','Chef Marco Vieri','Executive Chef & Founder','Join ingredients to suppliers matching category names, and calculate total value of inventory supplied by category.','JOIN ingredients with suppliers on category, SUM(unit_cost * current_stock_qty).',['SELECT','INNER JOIN','SUM','Arithmetic','GROUP BY','ORDER BY'],['supplier_category','total_category_stock_value'],"SELECT s.category AS supplier_category, ROUND(SUM(i.unit_cost * i.current_stock_qty), 2) AS total_category_stock_value FROM ingredients i JOIN suppliers s ON i.category = s.category GROUP BY s.category ORDER BY total_category_stock_value DESC;",'t',['Join ingredients with suppliers matching category.','Group by category and sum stock holding values.'],'Aligns physical warehouse stock value with supply contracts.',35,8),
  q('rest-L3-096','restaurants',3,96,'boss','Venues With Full Outdoor Garden Capacity','Giulia Conti','Director of Hospitality','Find restaurants that have at least one outdoor dining section and more than 100 total seats.','JOIN restaurants with dining_sections WHERE is_outdoor = TRUE and seating_capacity > 100.',['SELECT','DISTINCT','INNER JOIN','WHERE','AND'],['name','city','seating_capacity'],"SELECT DISTINCT r.name, r.city, r.seating_capacity FROM restaurants r JOIN dining_sections ds ON r.id = ds.restaurant_id WHERE ds.is_outdoor = TRUE AND r.seating_capacity > 100 ORDER BY r.name;",'f',['Join restaurants with dining_sections.','Filter WHERE is_outdoor = TRUE AND seating_capacity > 100.'],'Summer campaign marketing candidates with outdoor terraces.',30,6),
  q('rest-L3-097','restaurants',3,97,'boss','Unordered Menu Items Impact on Revenue Potential','Chef Marco Vieri','Executive Chef & Founder','List all menu items that have zero orders recorded, displaying potential revenue if each sold 10 units.','LEFT JOIN menu_items with order_items WHERE oi.id IS NULL.',['SELECT','LEFT JOIN','WHERE','IS NULL','Arithmetic'],['name','category','price','potential_lost_revenue'],"SELECT mi.name, mi.category, mi.price, ROUND(mi.price * 10, 2) AS potential_lost_revenue FROM menu_items mi LEFT JOIN order_items oi ON mi.id = oi.menu_item_id WHERE oi.id IS NULL ORDER BY mi.price DESC;",'f',['Left join menu_items with order_items.','Filter WHERE oi.id IS NULL and calculate price * 10.'],'Highlights unrealized gross potential on dead-stock recipes.',30,7),
  q('rest-L3-098','restaurants',3,98,'boss','Top 3 Suppliers by Spend in New York','Elena Rossi','Beverage & Cellar Director','Which 3 suppliers receive the highest procurement spend from restaurants located in New York City?','JOIN suppliers, ingredient_purchases, restaurants WHERE city = New York.',['SELECT','INNER JOIN','WHERE','SUM','GROUP BY','ORDER BY','LIMIT'],['supplier_name','ny_spend'],"SELECT s.supplier_name, SUM(ip.total_amount) AS ny_spend FROM suppliers s JOIN ingredient_purchases ip ON s.id = ip.supplier_id JOIN restaurants r ON ip.restaurant_id = r.id WHERE r.city = 'New York' GROUP BY s.supplier_name ORDER BY ny_spend DESC LIMIT 3;",'t',['Join suppliers, ingredient_purchases, restaurants.','Filter WHERE city = New York and sum spend LIMIT 3.'],'Key supplier exposure in our largest metropolitan territory.',35,8),
  q('rest-L3-099','restaurants',3,99,'boss','Comprehensive Menu Margin vs Food Cost Audit','Chef Marco Vieri','Executive Chef & Founder','Full kitchen audit: count of dishes, average retail price, average food cost, and overall network average gross margin %.','Single-row aggregate over menu_items.',['SELECT','COUNT','AVG','Arithmetic'],['total_dishes','avg_price','avg_cost','overall_margin_pct'],"SELECT COUNT(*) AS total_dishes, ROUND(AVG(price), 2) AS avg_price, ROUND(AVG(cost), 2) AS avg_cost, ROUND(AVG((price - cost) / price) * 100, 1) AS overall_margin_pct FROM menu_items;",'f',['Aggregate entire menu_items catalog for culinary executive benchmark.'],'Executive culinary unit economics health scorecard.',30,6),
  q('rest-L3-100','restaurants',3,100,'boss','Grand Food Cost vs Revenue Reconciliation','Chef Marco Vieri','Executive Chef & Founder','Grand corporate reconciliation: total order revenue recorded, total ingredient purchases recorded, and gross purchasing ratio %.','Cross-table reconciliation combining orders and ingredient_purchases totals.',['SELECT','SUM','Arithmetic','Subquery'],['total_order_revenue','total_procurement_cost','cost_of_goods_pct'],"SELECT (SELECT ROUND(SUM(total_amount), 2) FROM orders) AS total_order_revenue, (SELECT ROUND(SUM(total_amount), 2) FROM ingredient_purchases) AS total_procurement_cost, ROUND(((SELECT SUM(total_amount) FROM ingredient_purchases) / (SELECT SUM(total_amount) FROM orders)) * 100, 1) AS cost_of_goods_pct;",'f',['Scalar subqueries calculate total order sales and total procurement costs.','Compute procurement-to-sales ratio percentage.'],'The ultimate corporate food-cost ratio benchmark across the enterprise.',50,15),
];

